/// Full AB/P0/P1/P2/PS/P3/P4/P6/P7 driver. `families` is the passed FamilyPlans dependency.
pub fn owner_step(
    a: &Admitted,
    img: &mut MachineImage,
    families: &dyn FamilyPlans,
    guards: &OwnerGuards,
) -> Result<StepResult, HostViolation> {
    PreImage::bind(a, img)?; // AB first, before any table read.
    if img.fin.is_some() {
        return Err(fin_unsupported(FinUnsupportedOp::Step));
    }
    if img.outcome != OutcomeC::Running {
        return Ok(StepResult::Terminal);
    } // P0
    let pre_snap = snap(&PreImage::bind(a, img)?)?; // pure pre-image event snapshot; no write precedes it
    // P1 publish (helper and result absent only).
    if img.helper.is_none() && img.result.is_none() {
        match img.control {
            ControlC::Error { code } => {
                img.outcome = OutcomeC::Rejected { code };
                return Ok(publish_event(
                    a,
                    &pre_snap,
                    img,
                    RuleIdC::KAdminPublishError,
                    StepDisposition::Published,
                    None,
                    None,
                ));
            }
            ControlC::Return { value } if img.frames.is_empty() => {
                img.outcome = OutcomeC::Halted { value };
                return Ok(publish_event(
                    a,
                    &pre_snap,
                    img,
                    RuleIdC::KAdminPublishValue,
                    StepDisposition::Published,
                    None,
                    None,
                ));
            }
            _ => {}
        }
    }
    if img.remaining_work == 0 {
        img.outcome = OutcomeC::Exhausted {
            reason: ExhaustReason::Fuel,
        }; // P2
        return Ok(publish_event(
            a,
            &pre_snap,
